end;


function ParseNestedParens(parenString: string): array of integer;
begin
  var maxLevel := 0;
  var currentLevel := 0;
  var maxLevels := new List<integer>;
  var currentLevels := new List<integer>;
  var stack := new Stack<integer>;
  var chars := parenString.ToCharArray;

  foreach var ch in chars do
  begin
    if ch = '(' then
    begin
      currentLevel += 1;
      stack.Push(currentLevel);
      if currentLevel > maxLevel then
        maxLevel := currentLevel;
    end
    else if ch = ')' then
    begin
      currentLevel -= 1;
      currentLevels.Add(currentLevel);
      if currentLevel = 0 then
      begin
        maxLevels.Add(currentLevels.Max);
        currentLevels.Clear;
      end;
    end;
  end;

  Result := maxLevels.ToArray;
end;


