function HowManyTimes(str: string; substring: string): integer;
begin
  var count := 0;
  var i := 0;
  while i <= str.Length - substring.Length do
  begin
    var j := 0;
    while (j < substring.Length) and (str[i + j] = substring[j]) do
      j += 1;
    if j = substring.Length then
      count += 1;
    i += 1;
  end;
  Result := count;
end;


