function LargestDivisor(n: integer): integer;
begin
  Result := n - 1;
  while Result >= 2 do
  begin
    if n mod Result = 0 then
      exit(Result);
    Result -= 1;
  end;
  Result := 2;
end;


function Factorize(n: integer): array of integer;
begin
  var i := 2;
  var factors := new List<integer>;
  var num := n;

  while i * i <= n do
  begin
    if num mod i = 0 then
    begin
      factors.Add(i);
      num := num div i;
    end
    else
      i += 1;
  end;

  if num > 1 then
    factors.Add(num);

  Result := factors.ToArray;
end;


