function EncodeCyclic(s : string): string;
{ returns encoded string by cycling groups of three characters. }
begin
  var groups := new List<string>;
  var i := 0;
  while i < s.Length do
  begin
    var group_length := Min(3, s.Length - i);
    groups.Add(s.Substring(i, group_length));
    i += 3;
  end;
  for var j := 0 to groups.Count - 1 do
  begin
    if groups[j].Length = 3 then
      groups[j] := groups[j].Substring(1, 2) + groups[j][1];
  end;
  Result := string.Join('', groups.ToArray);
end;
function DecodeCyclic(s: string): string;
begin
  var groups := new List<string>;
  var i := 0;
  while i < s.Length do
  begin
    var group_length := Min(3, s.Length - i);
    groups.Add(s.Substring(i, group_length));
    i += 3;
  end;

  for var j := 0 to groups.Count - 1 do
  begin
    if groups[j].Length = 3 then
      groups[j] := groups[j].Substring(1, 2) + groups[j][1];
  end;

  Result := string.Join('', groups.ToArray);
end;


function PrimeFib(n: integer): integer;

  function IsPrime(num: integer): boolean;
  begin
    if num < 2 then
      Result := False
    else
    begin
      for var i := 2 to Trunc(Sqrt(num)) do
        if num mod i = 0 then
        begin
          Result := False;
          exit;
        end;
      Result := True;
    end;
  end;

  function IsFibonacci(num: integer): boolean;
  begin
    var a := 0;
    var b := 1;
    while b < num do
    begin
      var temp := a;
      a := b;
      b := temp + b;
    end;
    Result := b = num;
  end;

begin
  var count := 0;
  var num := 0;
  while count < n do
  begin
    if IsPrime(num) and IsFibonacci(num) then
    begin
      count += 1;
      Result := num;
    end;
    num += 1;
  end;
end;


function TriplesSumToZero(l: array of integer): boolean;
begin
  var sorted := l.ToArray;
  sorted.Sort;
  for var i := 0 to sorted.Length - 3 do
  begin
    if (i > 0) and (sorted[i] = sorted[i - 1]) then
      continue;
    var left := i + 1;
    var right := sorted.Length - 1;
    while left < right do
    begin
      var sum := sorted[i] + sorted[left] + sorted[right];
      if sum = 0 then
      begin
        Result := True;
        exit;
      end
      else if sum < 0 then
        left += 1
      else
        right -= 1;
    end;
  end;
  Result := False;
end;


