function ChangeBase(x: integer; base: integer): string;
begin
  if (x = 0) or (base < 2) or (base > 10) then
  begin
    Result := '0';
    exit;
  end;

  var digits := '0123456789ABCDEFGHIJK';
  var sb := new StringBuilder;

  while x > 0 do
  begin
    sb.Insert(0, digits[x mod base + 1]);
    x := x div base;
  end;

  Result := sb.ToString;
end;


