function Pluck(arr: array of integer): array of integer;
begin
  var smallestEven := integer.MaxValue;
  var smallestIndex := integer.MaxValue;
  var smallestValue := integer.MaxValue;
  for var i := 0 to arr.Length - 1 do
  begin
    if (arr[i] mod 2 = 0) and (arr[i] < smallestEven) then
    begin
      smallestEven := arr[i];
      smallestIndex := i;
    end;
  end;
  if smallestEven <> integer.MaxValue then
  begin
    smallestValue := smallestEven;
    Result := |smallestValue, smallestIndex|;
  end
  else
    Result := #[];
end;


function Search(lst: array of integer): integer;
begin
  var count := new Dictionary<integer, integer>;
  foreach var num in lst do
    if count.ContainsKey(num) then
      count[num] += 1
    else
      count[num] := 1;

  var maxFreq := count.Values.Max;
  for var i := maxFreq to 0 do
  begin
    if count.ContainsKey(i) and (count[i] >= i) then
    begin
      Result := i;
      exit;
    end;
  end;

  Result := -1;
end;


function StrangeSortList(lst: array of integer): array of integer;
begin
  if lst.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var sorted := lst.ToArray;
  sorted.Sort;

  var resultList := new List<integer>;
  while sorted.Count > 0 do
  begin
    resultList.Add(sorted[0]);
    sorted.RemoveAt(0);

    if sorted.Count > 0 then
    begin
      resultList.Add(sorted[sorted.Count - 1]);
      sorted.RemoveAt(sorted.Count - 1);
    end;
  end;

  Result := resultList.ToArray;
end;


function TriangleArea(a, b, c: real): real;
begin
  if (a + b > c) and (a + c > b) and (b + c > a) then
  begin
    var s := (a + b + c) / 2;
    Result := Round(Sqrt(s * (s - a) * (s - b) * (s - c)), 2);
  end
  else
    Result := -1;
end;


function WillItFly(q: array of integer; w: integer): boolean;
begin
  var isBalanced := true;
  var sum := 0;

  for var i := 0 to q.Length - 1 do
  begin
    sum += q[i];

    if q[i] <> q[q.Length - 1 - i] then
    begin
      isBalanced := false;
      break;
    end;
  end;

  Result := isBalanced and (sum <= w);
end;


function SmallestChange(arr: array of integer): integer;
begin
  var n := arr.Length;
  var dp := new integer[n + 1, n + 1];

  for var i := 0 to n do
    dp[i, n] := n - i;

  for var j := n - 1 downto 0 do
  begin
    var max := n - j;
    for var i := 0 to j - 1 do
    begin
      if arr[i] = arr[j] then
        dp[i, j] := dp[i + 1, j - 1]
      else
        dp[i, j] := min(dp[i + 1, j], dp[i, j - 1]) + 1;

      if dp[i, j] <= max then
        max := dp[i, j];
    end;
    dp[j, j] := max;
  end;

  Result := dp[0, n - 1];
end;


