function IsMultiplyPrime(a: integer): boolean;
begin
  var primes := new List<integer>;
  var n := a;
  var i := 2;
  while i * i <= n do
  begin
    if n mod i = 0 then
    begin
      primes.Add(i);
      n := n div i;
    end
    else
      i += 1;
  end;
  if n > 1 then
    primes.Add(n);
  Result := primes.Count = 3;
end;


