function DecimalToBinary(decimal: integer): string;
begin
  var binary := '';
  var num := decimal;

  while num > 0 do
  begin
    binary := (num mod 2).ToString + binary;
    num := num div 2;
  end;

  Result := 'db' + binary + 'db';
end;


