      letterGrades.Add('A+')
    else if grade > 3.7 then
      letterGrades.Add('A')
    else if grade > 3.3 then
      letterGrades.Add('A-')
    else if grade > 3.0 then
      letterGrades.Add('B+')
    else if grade > 2.7 then
      letterGrades.Add('B')
    else if grade > 2.3 then
      letterGrades.Add('B-')
    else if grade > 2.0 then
      letterGrades.Add('C+')
    else if grade > 1.7 then
      letterGrades.Add('C')
    else if grade > 1.3 then
      letterGrades.Add('C-')
    else if grade > 1.0 then
      letterGrades.Add('D+')
    else if grade > 0.7 then
      letterGrades.Add('D')
    else if grade > 0.0 then
      letterGrades.Add('D-')
    else
      letterGrades.Add('E');
  end;

  Result := letterGrades.ToArray;
end;


