function StartsOneEnds(n: integer): integer;
begin
  if n = 1 then
    Result := 10
  else if n = 2 then
    Result := 17
  else
  begin
    var dp := new integer[n + 1];
    dp[1] := 10;
    dp[2] := 17;
    for var i := 3 to n do
    begin
      dp[i] := dp[i - 1] + dp[i - 2] * 10;
      dp[i] := dp[i] + dp[i - 2] * 90;
    end;
    Result := dp[n];
  end;
end;


