function Encode(message: string): string;
begin
  var vowels := 'aeiou';
  var encoded := new StringBuilder;

  for var i := 1 to message.Length do
  begin
    var ch := message[i];
    if char.IsLetter(ch) then
    begin
      if char.IsLower(ch) then
        ch := char.ToUpper(ch)
      else
        ch := char.ToLower(ch);

      if vowels.Contains(char.ToLower(ch)) then
        ch := char(Ord(ch) + 2);

      if char.IsLower(ch) then
        encoded.Append(char.ToLower(ch))
      else
        encoded.Append(char.ToUpper(ch));
    end
    else
      encoded.Append(ch);
  end;

  Result := encoded.ToString;
end;


