function CheckDictCase(dict: Dictionary<string, string>): boolean;
begin
  if dict.Count = 0 then
  begin
    Result := False;
    exit;
  end;

  var lowerKeys := dict.Keys.Select(k -> k.ToLower).ToArray;
  var upperKeys := dict.Keys.Select(k -> k.ToUpper).ToArray;

  Result := (lowerKeys.SequenceEqual(lowerKeys.OrderBy(k -> k))) or
            (upperKeys.SequenceEqual(upperKeys.OrderBy(k -> k)));
end;


function CountUpTo(n: integer): array of integer;
begin
  var primes := new List<integer>;
  for var i := 2 to n - 1 do
  begin
    var isPrime := True;
    for var j := 2 to i - 1 do
      if i mod j = 0 then
      begin
        isPrime := False;
        break;
      end;
    if isPrime then
      primes.Add(i);
  end;
  Result := primes.ToArray;
end;


function Multiply(a, b: integer): integer;
begin
  var product := 0;
  var aDigits := Abs(a);
  var bDigits := Abs(b);

  for var i := 1 to aDigits do
  begin
    var digit := a mod 10;
    product += digit * bDigits;
    a := a div 10;
  end;

  Result := product;
end;


