  if n > m then
  begin
    Result := '-1';
    exit;
  end;

  var total := 0;
  for var i := n to m do
    total += i;

  var avg := total / (m - n + 1);
  var rounded := Round(avg);

  Result := '0b' + Convert.ToString(rounded, 2);
end;


function UniqueDigits(x: array of integer): array of integer;
begin
  var uniqueDigits := new List<integer>;
  var digits := new HashSet<integer>;

  foreach var num in x do
  begin
    var numStr := num.ToString;
    foreach var ch in numStr do
      if (StrToInt(ch) mod 2 = 0) then
      begin
        digits.Add(StrToInt(ch));
        break;
      end;
  end;

  uniqueDigits.AddRange(digits);
  uniqueDigits.Sort;
  Result := uniqueDigits.ToArray;
end;


