function EvenOddPalindrome(n: integer): (integer, integer);
begin
  var evenCount := 0;
  var oddCount := 0;
  for var i := 1 to n do
  begin
    var numStr := i.ToString;
    if (numStr = numStr.Inverse.ToString) and (i mod 2 = 0) then
      evenCount += 1;
    if (numStr = numStr.Inverse.ToString) and (i mod 2 <> 0) then
      oddCount += 1;
  end;
  Result := (evenCount, oddCount);
end;


