      counts[word] := counts[word] + 1
    else
      counts[word] := 1;
  end;

  Result := counts;
end;


function ReverseDelete(s, c: string): (string, boolean);
begin
  var sb := new StringBuilder;
  foreach var ch in s do
    if not c.Contains(ch) then
      sb.Append(ch);
  var res := sb.ToString;
  var check := True;
  if res.Length > 0 then
  begin
    var i := 0;
    var j := res.Length - 1;
    while i < j do
    begin
      if res[i] <> res[j] then
      begin
        check := False;
        break;
      end;
      i += 1;
      j -= 1;
    end;
  end;
  Result := (res, check);
end;


