function Minsubarraysum(nums: array of integer): integer;
begin
  var minSum := integer.MaxValue;
  var currentSum := 0;

  for var i := 0 to nums.Length - 1 do
  begin
    currentSum := currentSum + nums[i];
    minSum := Min(minSum, currentSum);
    if currentSum < 0 then
      currentSum := 0;
  end;

  Result := minSum;
end;


function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var buckets := new integer[m, n];
  var count := 0;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i, j] = 1 then
      begin
        buckets[i, j] := 1;
        count += 1;
      end;

  var total := count;
  var i := 0;

  while (i < m) and (total < capacity) do
  begin
    for var j := 0 to n - 1 do
      if (grid[i, j] = 1) and (buckets[i, j] = 0) then
      begin
        buckets[i, j] := 1;
        total += 1;
        break;
      end;
    i += 1;
  end;

  Result := total;
end;


