    foreach var ch in word do
      if (ch <> ' ') and (not char.IsVowel(ch)) then
        count += 1;

    if count = n then
      res.Add(word);
  end;

  Result := res.ToArray;
end;


function GetClosestVowel(word: string): string;
begin
  var vowels := 'aeiouAEIOU';
  var left := 0;
  var right := word.Length - 1;
  var closestVowel := '';

  while left < right do
  begin
    var leftChar := word[left + 1];
    var rightChar := word[right + 1];

    if (vowels.Contains(leftChar) and vowels.Contains(rightChar)) and 
       (not vowels.Contains(leftChar) and not vowels.Contains(rightChar)) then
    begin
      closestVowel := word[left + 1];
      break;
    end;

    if (vowels.Contains(leftChar) and not vowels.Contains(rightChar)) or 
       (not vowels.Contains(leftChar) and vowels.Contains(rightChar)) then
    begin
      closestVowel := word[right + 1];
      break;
    end;

    left += 1;
    right -= 1;
  end;

  Result := closestVowel;
end;


function MatchParens(lst: array of string): string;
begin
  var s := lst.JoinToString;
  var stack := new Stack<char>;
  foreach var ch in s do
  begin
    if ch = '(' then
      stack.Push(ch)
    else if (ch = ')') and (stack.Count = 0) then
    begin
      Result := 'No';
      exit;
    end
    else
      stack.Pop;
  end;
  Result := (stack.Count = 0) ? 'Yes' : 'No';
end;


