function GetOddCollatz(n: integer): array of integer;
begin
  var collatz := new List<integer>;
  collatz.Add(1);
  var current := n;
  while current <> 1 do
  begin
    if current mod 2 <> 0 then
      collatz.Add(current);
    current := if current mod 2 = 0 then current div 2 else 3 * current + 1;
  end;
  Result := collatz.ToArray;
end;


function ValidDate(date: string): boolean;
begin
  var parts := date.Split('-');
  if parts.Length <> 3 then
  begin
    Result := False;
    exit;
  end;
  var month := StrToInt(parts[0]);
  var day := StrToInt(parts[1]);
  var year := StrToInt(parts[2]);
  if (month < 1) or (month > 12) or (day < 1) or (day > 31) then
  begin
    Result := False;
    exit;
  end;
  if month = 2 then
  begin
    if day > 29 then
    begin
      Result := False;
      exit;
    end;
  end
  else if month in [4, 6, 9, 11] then
  begin
    if day > 30 then
    begin
      Result := False;
      exit;
    end;
  end
  else if month = 12 then
  begin
    if day > 31 then
    begin
      Result := False;
      exit;
    end;
  end;
  Result := True;
end;


