function ProdSigns(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var sign := 1;
  var product := 1;
  var sum := 0;

  foreach var num in arr do
  begin
    if num = 0 then
    begin
      Result := 0;
      exit;
    end;

    sign := sign * (num > 0) - (num < 0);
    product := product * Abs(num);
    sum := sum + Abs(num);
  end;

  Result := sign * product;
end;


function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var directions := new integer[4, 2] := (
    (0, 1),
    (0, -1),
    (1, 0),
    (-1, 0)
  );
  var visited := new boolean[n, n];
  var queue := new Queue<(integer, integer, integer)>;
  queue.Enqueue((-1, -1, 0));
  var res := new List<integer>;

  while queue.Count > 0 do
  begin
    var (x, y, steps) := queue.Dequeue;

    if (x = n - 1) and (y = n - 1) then
    begin
      res.Add(grid[x, y]);
      continue;
    end;

    for var i := 0 to 3 do
    begin
      var nx := x + directions[i, 0];
      var ny := y + directions[i, 1];

      if (nx >= 0) and (nx < n) and (ny >= 0) and (ny < n) and not visited[nx, ny] then
      begin
        visited[nx, ny] := true;
        queue.Enqueue((nx, ny, steps + 1));
      end;
    end;
  end;

  res.Sort;
  Result := res.ToArray;
end;


function Tri(n: integer): array of real;
begin
  var tri := new List<real>;
  tri.Add(3);
  if n = 0 then
  begin
    Result := tri.ToArray;
    exit;
  end;
  tri.Add(1);
  if n = 1 then
  begin
    Result := tri.ToArray;
    exit;
  end;
  tri.Add(2);
  for var i := 3 to n do
  begin
    if i mod 2 = 0 then
      tri.Add(tri[i - 1] + tri[i - 2] + i div 2)
    else
      tri.Add(tri[i - 1] + tri[i - 2] + tri[i - 3]);
  end;
  Result := tri.ToArray;
end;


function Digits(n: integer): integer;
begin
  var product := 1;
  var hasOdd := False;
  var num := n;

  while num > 0 do
  begin
    var digit := num mod 10;
    if digit mod 2 <> 0 then
    begin
      product *= digit;
      hasOdd := True;
    end;
    num := num div 10;
  end;

  if hasOdd then
    Result := product
  else
    Result := 0;
end;


function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var ch in s do
  begin
    if ch = '[' then
      stack.Push(ch)
    else if ch = ']' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  end;
  Result := stack.Count = 0;
end;


