  var maxIndex := -1;
  var maxVal := integer.MinValue;
  for var i := n - 1 downto 0 do
  begin
    if arr[i] >= maxVal then
    begin
      maxIndex := i;
      maxVal := arr[i];
    end;
  end;
  Result := maxIndex;
end;


function LargestSmallestIntegers(lst: array of integer): (integer, integer);
begin
  var negatives := lst.Where(x -> x < 0).ToArray;
  var positives := lst.Where(x -> x > 0).ToArray;

  if negatives.Length = 0 then
    Result := (0, positives.Length > 0 ? positives[0] : 0)
  else if positives.Length = 0 then
    Result := (negatives[0], 0)
  else
  begin
    var maxNegative := negatives.Max;
    var minPositive := positives.Min;
    Result := (maxNegative, minPositive);
  end;
end;


function CompareOne(a, b: object): object;
begin
  if a is integer then
  begin
    if b is integer then
      Result := integer(Max(integer(a), integer(b)))
    else
      Result := integer(b);
  end
  else if a is real then
  begin
    if b is real then
      Result := real(Max(real(a), real(b)))
    else
      Result := real(b);
  end
  else if a is string then
  begin
    if b is string then
    begin
      var aVal := real(a);
      var bVal := real(b);
      if aVal.ToString.Contains(',') then
        aVal := real(aVal.ToString.Replace(',', '.'));
      if bVal.ToString.Contains(',') then
        bVal := real(bVal.ToString.Replace(',', '.'));
      Result := real(Max(aVal, bVal));
    end
    else
      Result := real(b);
  end
  else
    Result := b;
end;


