function FixSpaces(text: string): string;
begin
  var sb := new StringBuilder;
  var count := 0;

  foreach var ch in text do
  begin
    if ch = ' ' then
    begin
      count += 1;
      if count > 2 then
        sb.Append('-')
      else
        sb.Append('_');
    end
    else
    begin
      sb.Append(ch);
      count := 0;
    end;
  end;

  Result := sb.ToString;
end;


