function WordsInSentence(sentence: string): string;
begin
  var words := sentence.Split(' ');
  var primeWords := new List<string>;

  foreach var word in words do
  begin
    var length := word.Length;
    var isPrime := True;

    for var i := 2 to Trunc(Sqrt(length)) do
      if length mod i = 0 then
      begin
        isPrime := False;
        break;
      end;

    if isPrime then
      primeWords.Add(word);
  end;

  Result := string.Join(' ', primeWords);
end;


