function Bf(planet1, planet2: string): array of string;
begin
  var planets := |'Mercury', 'Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune'|;
  var planet1Index := -1;
  var planet2Index := -1;

  for var i := 0 to planets.Length - 1 do
    if planets[i] = planet1 then
      planet1Index := i
    else if planets[i] = planet2 then
      planet2Index := i;

  if (planet1Index = -1) or (planet2Index = -1) then
  begin
    Result := new string[0];
    exit;
  end;

  if planet1Index < planet2Index then
  begin
    Result := planets.Skip(planet1Index + 1).Take(planet2Index - planet1Index - 1).ToArray;
  end
  else
  begin
    Result := planets.Skip(planet2Index + 1).Take(planet1Index - planet2Index - 1).Reverse.ToArray;
  end;
end;


