  sides.Add(c);
  sides.Sort;
  Result := (sides[0] * sides[0]) + (sides[1] * sides[1]) = (sides[2] * sides[2]);
end;


function FindMax(words: array of string): string;
begin
  var maxUnique := 0;
  var maxWord := '';
  foreach var word in words do
  begin
    var uniqueCount := word.Distinct.Count;
    if uniqueCount > maxUnique then
    begin
      maxUnique := uniqueCount;
      maxWord := word;
    end;
  end;
  Result := maxWord;
end;


function Eat(number, need, remaining: integer): (integer, integer);
begin
  var eaten := Min(need, remaining);
  Result := (number + eaten, remaining - eaten);
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 0 to operand.Length - 2 do
  begin
    case op[i] of
      '+': res += operand[i + 1];
      '-': res -= operand[i + 1];
      '*': res *= operand[i + 1];
      '//': res := Trunc(res / operand[i + 1]);
      '**': res := Round(Power(res, operand[i + 1]));
    end;
  end;
  Result := res;
end;


function Solve(s: string): string;
begin
  var sb := new StringBuilder;
  var isLetter := false;
  foreach var ch in s do
  begin
    if char.IsLetter(ch) then
    begin
      isLetter := true;
      if char.IsLower(ch) then
        sb.Append(char.ToUpper(ch))
      else
        sb.Append(char.ToLower(ch));
    end
    else
    begin
      isLetter := false;
      sb.Append(ch);
    end;
  end;
  if not isLetter then
    sb.Reverse;
  Result := sb.ToString;
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
  begin
    Result := nil;
    exit;
  end;

  var hasher := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var inputBytes := System.Text.Encoding.ASCII.GetBytes(text);
  var theHash := hasher.ComputeHash(inputBytes);

  var sb := new System.Text.StringBuilder;
  for var i := 0 to theHash.Length - 1 do
    sb.Append(theHash[i].ToString('x2'));
  Result := sb.ToString;
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  var evenDigits := new List<integer>;

  for var i := a to b do
    if i mod 2 = 0 then
      evenDigits.Add(i);

  Result := evenDigits.ToArray;
end;
